+        if (obj == this) {
+            return true;
+        }
+
+        if (!(obj instanceof TaggedUnion)) {
+            return false;
+        }
+
+        TaggedUnion<?, ?> other = (TaggedUnion<?, ?>) obj;
+        return Objects.equals(one, other.one) && Objects.equals(two, other.two);
+    }
