+
+        if (triggerResult.isFire()) {
+            emitWindowContents(triggerContext.getWindow());
+        }
+
+        if (triggerResult.isPurge()) {
+            windowState.clear();
+        }
+
+        if (windowAssigner.isEventTime()
+                && WindowUtils.isCleanupTime(
+                        triggerContext.getWindow(),
+                        timer.getTimestamp(),
+                        windowAssigner,
+                        allowedLateness)) {
