+    // ------------------------------------------------------------------------
+    // Operator components
+    // ------------------------------------------------------------------------
+
+    private transient InternalTimerService<W> internalTimerService;
+
+    /** For serializing the window in checkpoints. */
+    private final TypeSerializer<W> windowSerializer;
+
+    // ------------------------------------------------------------------------
