+                        mergingWindows.addWindow(
+                                window,
+                                new MergingWindowSet.MergeFunction<>() {
+                                    @Override
+                                    public void merge(
+                                            W mergeResult,
+                                            Collection<W> mergedWindows,
+                                            W stateWindowResult,
+                                            Collection<W> mergedStateWindows)
