+
+    // ------------------------------------------------------------------------
+    // Configuration values and user functions
+    // ------------------------------------------------------------------------
+
+    private final TwoOutputWindowStreamProcessFunction<IN, OUT_MAIN, OUT_SIDE>
+            windowProcessFunction;
+
+    /**
+     * The allowed lateness for elements. This is used for:
