+            InternalTwoOutputWindowStreamProcessFunction<IN, OUT_MAIN, OUT_SIDE, W>
+                    windowProcessFunction,
+            OutputTag<OUT_SIDE> outputTag,
+            @Nullable KeySelector<OUT_MAIN, K> mainOutKeySelector,
+            @Nullable KeySelector<OUT_SIDE, K> sideOutKeySelector,
+            WindowAssigner<? super IN, W> windowAssigner,
+            Trigger<? super IN, ? super W> trigger,
+            TypeSerializer<W> windowSerializer,
+            StateDescriptor<IN> windowStateDescriptor,
+            long allowedLateness) {
