+        env.execute("testOneInputWindowFunctionWithEventTimeGlobalWindow");
+
+        assertThat(TestCollectResultProcessFunction.elementSum)
+                .isEqualTo(EXPECTED_ELEMENT_SUM_PER_SOURCE);
