+                                            throws Exception {
+                                        Optional<ValueState<Long>> countState =
+                                                windowContext.getWindowState(countStateDeclaration);
+                                        if (countState.isPresent()
+                                                && countState.get().value() != null) {
+                                            countState.get().update(countState.get().value() + 1);
