+                .asyncEntries()
+                .thenCompose(
+                        iter ->
+                                iter.onNext(
+                                        entry -> {
+                                            RowData sortKey = entry.getKey();
+                                            List<RowData> values = entry.getValue();
+                                            // the order is preserved
+                                            bufferFromState.putAll(sortKey, values);
+                                        }))
