+        RowData sortKey = sortKeySelector.getKey(input);
+        topNBufferFuture.thenCombine(
+                rankEndFuture,
+                (buffer, rankEnd) -> {
+                    if (checkSortKeyInBufferRange(sortKey, buffer)) {
+                        // insert sort key into buffer
