+        if (buffer.getCurrentTopNum() > rankEnd) {
+            Map.Entry<RowData, Collection<RowData>> lastEntry = buffer.lastEntry();
+            RowData lastKey = lastEntry.getKey();
+            Collection<RowData> lastList = lastEntry.getValue();
